(*----- Function stock_init_storage -----*)

Definition stock_init_storage_safety_wit_1 := 
forall (length_pre: Z) (storage_pre: Z) (PreH1 : (0 <= length_pre)) (PreH2 : (length_pre <= 982081)) ,
  ((( &( "index" ) )) # Int  |->_)
  **  ((( &( "storage" ) )) # Ptr  |-> storage_pre)
  **  ((( &( "length" ) )) # Int  |-> length_pre)
  **  (IntArray.undef_full storage_pre length_pre )
|--
  “ (0 <= INT_MAX) ” 
  &&  “ ((INT_MIN) <= 0) ”
.

Definition stock_init_storage_safety_wit_2 := 
forall (length_pre: Z) (storage_pre: Z) (cells: (@list Z)) (index: Z) (PreH1 : (index < length_pre)) (PreH2 : (0 <= length_pre)) (PreH3 : (length_pre <= 982081)) (PreH4 : (0 <= index)) (PreH5 : (index <= length_pre)) (PreH6 : ((Zlength (cells)) = index)) ,
  ((( &( "storage" ) )) # Ptr  |-> storage_pre)
  **  ((( &( "length" ) )) # Int  |-> length_pre)
  **  ((( &( "index" ) )) # Int  |-> index)
  **  (IntArray.seg storage_pre 0 index cells )
  **  (IntArray.undef_seg storage_pre index length_pre )
|--
  “ (0 <= INT_MAX) ” 
  &&  “ ((INT_MIN) <= 0) ”
.

Definition stock_init_storage_safety_wit_3 := 
forall (length_pre: Z) (storage_pre: Z) (cells: (@list Z)) (index: Z) (PreH1 : (index < length_pre)) (PreH2 : (0 <= length_pre)) (PreH3 : (length_pre <= 982081)) (PreH4 : (0 <= index)) (PreH5 : (index <= length_pre)) (PreH6 : ((Zlength (cells)) = index)) ,
  (IntArray.seg storage_pre 0 (index + 1 ) (app (cells) ((cons (0) ((@nil Z))))) )
  **  (IntArray.undef_seg storage_pre (index + 1 ) length_pre )
  **  ((( &( "storage" ) )) # Ptr  |-> storage_pre)
  **  ((( &( "length" ) )) # Int  |-> length_pre)
  **  ((( &( "index" ) )) # Int  |-> index)
|--
  “ ((index + 1 ) <= INT_MAX) ” 
  &&  “ ((INT_MIN) <= (index + 1 )) ”
.

Definition stock_init_storage_entail_wit_1 := 
(
forall (length_pre: Z) (storage_pre: Z) (PreH1 : (0 <= length_pre)) (PreH2 : (length_pre <= 982081)) ,
  (IntArray.undef_full storage_pre length_pre )
|--
  EX (cells: (@list Z)) ,
  “ (0 <= length_pre) ” 
  &&  “ (length_pre <= 982081) ” 
  &&  “ (0 <= 0) ” 
  &&  “ (0 <= length_pre) ” 
  &&  “ ((Zlength (cells)) = 0) ”
  &&  (IntArray.seg storage_pre 0 0 cells )
  **  (IntArray.undef_seg storage_pre 0 length_pre )
) \/
(
forall (length_pre: Z) (PreH1 : (0 <= length_pre)) (PreH2 : (length_pre <= 982081)) ,
  TT && emp 
|--
  “ ((Zlength ((@nil Z))) = 0) ”
  &&  emp
).

Definition stock_init_storage_entail_wit_1_split_goal_1 := 
forall (length_pre: Z) (PreH1 : (0 <= length_pre)) (PreH2 : (length_pre <= 982081)) ,
  ((Zlength ((@nil Z))) = 0)
.

Definition stock_init_storage_entail_wit_2 := 
(
forall (length_pre: Z) (storage_pre: Z) (cells_2: (@list Z)) (index: Z) (PreH1 : (index < length_pre)) (PreH2 : (0 <= length_pre)) (PreH3 : (length_pre <= 982081)) (PreH4 : (0 <= index)) (PreH5 : (index <= length_pre)) (PreH6 : ((Zlength (cells_2)) = index)) ,
  (IntArray.seg storage_pre 0 (index + 1 ) (app (cells_2) ((cons (0) ((@nil Z))))) )
  **  (IntArray.undef_seg storage_pre (index + 1 ) length_pre )
|--
  EX (cells: (@list Z)) ,
  “ (0 <= length_pre) ” 
  &&  “ (length_pre <= 982081) ” 
  &&  “ (0 <= (index + 1 )) ” 
  &&  “ ((index + 1 ) <= length_pre) ” 
  &&  “ ((Zlength (cells)) = (index + 1 )) ”
  &&  (IntArray.seg storage_pre 0 (index + 1 ) cells )
  **  (IntArray.undef_seg storage_pre (index + 1 ) length_pre )
) \/
(
forall (length_pre: Z) (cells_2: (@list Z)) (index: Z) (PreH1 : (index < length_pre)) (PreH2 : (0 <= length_pre)) (PreH3 : (length_pre <= 982081)) (PreH4 : (0 <= index)) (PreH5 : (index <= length_pre)) (PreH6 : ((Zlength (cells_2)) = index)) ,
  TT && emp 
|--
  “ ((Zlength ((app (cells_2) ((cons (0) ((@nil Z))))))) = (index + 1 )) ”
  &&  emp
).

Definition stock_init_storage_entail_wit_2_split_goal_1 := 
forall (length_pre: Z) (cells_2: (@list Z)) (index: Z) (PreH1 : (index < length_pre)) (PreH2 : (0 <= length_pre)) (PreH3 : (length_pre <= 982081)) (PreH4 : (0 <= index)) (PreH5 : (index <= length_pre)) (PreH6 : ((Zlength (cells_2)) = index)) ,
